INSERT INTO `doctors` (`category_id`,`sub_category_id`,`name`,`designation`,`image_path`,`degree`,`higher_degree`,`phone`,`bmdc_number`,`email`,`work_place`,`specialist_in`,`experience_years`,`fee`,`about`,`priority`,`status`,`editing_status`) VALUES (7, 31, 'Dr. Mohammad Mohitul Islam', 'ASSOCIATE PROFESSOR ( NEUROLOGY DEPARTMENT) , Chattogram Medical College & Hospital', 'assets/images/doctors/doc6.png', 'MBBS, BCS(HEALTH)', 'MD(NEUROMEDICINE),BSMMU, For Appointment Call : 01813501952', '01812345622', '12322', 'admin22@gmail.com', 'National Hospital Chittagong', 'Neuro Medicine', 10, 1000, 'Dr. Mohammad Mohitul Islam is a Neuromedicine Specialist in Chittagong, Bangladesh. With an MD in Neuro Medicine and years of experience, he offers exceptional care for patients with brain-related conditions. As an Associate Professor at Chittagong Medical College Hospital, Dr. Mohammad Mohitul Islam expertise extends to various neurological disorders, including migraines, epilepsy, stroke, movement disorders, and neuropathies. Patients can consult him at National Hospital Chattagram, Room No. 4016, on Sundays, Tuesdays, and Thursdays from 06:00 pm to 09:00 pm. Dr. Mohammad Mohitul Islam profound knowledge, dedication, and comprehensive approach make him a trusted specialist who brings hope and healing to his patients, impacting their lives positively.', 0, 'approved', 'unlocked');
