INSERT INTO `doctors` (`category_id`,`sub_category_id`,`name`,`designation`,`image_path`,`degree`,`higher_degree`,`phone`,`bmdc_number`,`email`,`work_place`,`specialist_in`,`experience_years`,`fee`,`about`,`priority`,`status`,`editing_status`) VALUES (7, 19, 'Dr. Md. Jamal Uddin Tanin', 'Faculty Of Medicine (BSMMU)', 'assets/images/doctors/doc9.png', 'MBBS (CMC),', 'MD (Hematology)', '01812345619', '12319', 'admin19@gmail.com', 'National Hospital Chittagong', 'Hematoligy', 10, 1000, 'Dr. Jamal Uddin Tanin, an esteemed Hematologist, holds the degrees of MBBS and MD (Hematology), showcasing his extensive medical expertise. With a notable focus on blood cancers and blood-related disorders, he has emerged as a dedicated specialist in his field. Dr. Tanin serves as a Consultant in the Department of Hematology at the esteemed National Hospital in Chittagong. His commitment to patient care is evident through his regular provision of treatment to those in need. Located at 14/15 Dampara Lane, Mehedibag, Chattogram, his chamber becomes a haven for those seeking expert medical attention. Patients can avail themselves of his services from 2 pm to 4 pm, barring Thursdays and Fridays. With a remarkable academic background and a strong presence at National Hospital, Chittagong, Dr. Jamal Uddin Tanin stands as a beacon of hope for individuals dealing with blood disorders, receiving compassionate and specialized care. To schedule an appointment, individuals can reach out at 018263265857 or 01827402322', 0, 'approved', 'unlocked');
