INSERT INTO `doctors` (`category_id`,`sub_category_id`,`name`,`designation`,`image_path`,`degree`,`higher_degree`,`phone`,`bmdc_number`,`email`,`work_place`,`specialist_in`,`experience_years`,`fee`,`about`,`priority`,`status`,`editing_status`) VALUES (7, 20, 'Prof. Dr. Md. Gias Uddin Sagor', 'Professor & Head of Dept. (Psychology Dept. ) CHATTOGARM MAA O SISHU MEDICAL COLLEGE HOSPITAL', 'assets/images/doctors/doc10.png', 'MBBS', 'M.Phil(Psychiatric), Room No : 2023', '01812345618', '12318', 'admin18@gmail.com', 'National Hospital Chittagong', 'Psychiatrist Specialist', 10, 1000, 'Prof. Dr. Md. Gias Uddin Sagor is a distinguished psychiatrist renowned for his expertise in mental health, brain disorders, headaches, and epilepsy. Holding impressive credentials including an MBBS and an M.Phil in Psychiatry, he stands as a beacon of knowledge and innovation in his field. Currently serving as the Professor and Head of the Department of Mental Diseases at Chattogram Maa-O-Shishu Hospital Medical College, Prof. Dr. Sagor\'s dedication to advancing psychiatric care is evident. Patients seeking his compassionate care can find solace at his chambers within the esteemed National Hospital in Chittagong. With visiting hours from 4pm to 7pm (excluding Friday and Saturday), Prof. Dr. Md. Gias Uddin Sagor ensures that his expertise and guidance remain accessible to those in need. His commitment to enhancing mental well-being and his contributions to the medical community make him a beacon of hope for individuals striving for improved mental health.', 0, 'approved', 'unlocked');
