INSERT INTO `doctors` (`category_id`,`sub_category_id`,`name`,`designation`,`image_path`,`degree`,`higher_degree`,`phone`,`bmdc_number`,`email`,`work_place`,`specialist_in`,`experience_years`,`fee`,`about`,`priority`,`status`,`editing_status`) VALUES (7, 21, 'Dr. Shafiul Karim Md Elias', 'Associate Professor & Head of Dept. at CIMC Hospital', 'assets/images/doctors/doc11.png', 'MBBS,', 'FCPS (Physical Medicine)', '01812345617', '12317', 'admin17@gmail.com', 'National Hospital Chittagong', 'Physical Medicine', 10, 1000, 'Dr. Shafiul Karim Md. Elias is a highly accomplished and respected Physical Medicine Specialist in Chittagong. His impressive qualifications include an MBBS degree and the prestigious FCPS in Physical Medicine, demonstrating his expertise in the field. Dr. Elias serves as an Associate Professor and is the Head of the Department of Physical Medicine & Rehabilitation at CIMC Hospital. His specialization encompasses a wide range of areas, including pain management, arthritis, paralysis, and sports injuries. Patients in search of expert care and guidance can visit his chamber at the National Hospital in Chittagong, where he is available for consultation every day, with the exception of Thursdays and Fridays, from 5 pm to 7 pm. To schedule an appointment and benefit from Dr. Shafiul Karim Md. Elias\'s extensive knowledge and experience, you can reach out to him at 01930715166 or 01827402322. Dr. Shafiul Karim dedication to the field of Physical Medicine and his commitment to patient well-being make him a trusted healthcare provider in the Chittagong.', 0, 'approved', 'unlocked');
