INSERT INTO `doctors` (`category_id`,`sub_category_id`,`name`,`designation`,`image_path`,`degree`,`higher_degree`,`phone`,`bmdc_number`,`email`,`work_place`,`specialist_in`,`experience_years`,`fee`,`about`,`priority`,`status`,`editing_status`) VALUES (7, 21, 'Prof. Dr. Zahangir Alam Chowdhury', 'Professor & Head of the Department of Physical Medicine and Rehabilitation at Chattogram Maa-O-Shishu Hospital', 'assets/images/doctors/doc12.png', 'MBBS', 'FCPS (Physical Medicine), Room No : 3022', '01812345616', '12316', 'admin16@gmail.com', 'National Hospital Chattogram & Sigma Lab Ltd.', 'Physical Medicine', 10, 1000, 'Professor Doctor Zahangir Alam Chowdhury is a highly esteemed and accomplished medical professional specializing in Physical Medicine and Rehabilitation. With his qualifications, which include an MBBS and FCPS in Physical Medicine, he possesses a deep understanding of the human body and its functions. Notably, he serves as the Professor and Head of the Department of Physical Medicine and Rehabilitation at Chattogram Maa-O-Shishu Hospital, where he imparts his extensive knowledge to train future healthcare practitioners. Dr. Chowdhury extends his expertise to his chambers at both National Hospital Chattogram and Sigma Lab Ltd., making his care accessible to patients. His visiting hours, from 3pm to 7pm every day (with Fridays off), ensure that individuals seeking his specialized care can conveniently do so. To schedule consultations, patients can reach out to him at 01916852155 or 01827402322.', 0, 'approved', 'unlocked');
