INSERT INTO `doctors` (`category_id`,`sub_category_id`,`name`,`designation`,`image_path`,`degree`,`higher_degree`,`phone`,`bmdc_number`,`email`,`work_place`,`specialist_in`,`experience_years`,`fee`,`about`,`priority`,`status`,`editing_status`) VALUES (7, 23, 'Dr. Mohammad Abdul Kader', 'Consultant, Dept. of Nephrology at Chittagong Medical College & Hospital', 'assets/images/doctors/doc11.png', 'MBBS, BCS (Health)', 'MD(Nephrology)', '01812345671', '12341', 'admin1@gmail.com', 'National Hospital Chittagong', 'Kidney Specialist', 10, 1000, 'Dr. Mohammad Abdul Kader is a distinguished Kidney Specialist renowned for his expertise in the field. Armed with an MBBS and BCS (Health) qualification and an M.D in Nephrology from Chittagong Medical College & Hospital, he stands as a beacon of medical proficiency. Dr. Kader\'s dedicated focus on kidney diseases has made him a sought-after practitioner in Chittagong. His chamber is at National Hospital, Chittagong, where he provides top-notch medical care. With a visiting schedule from 6:30 pm to 9:30 pm every day (excluding Fridays), patients can conveniently seek his specialized guidance. To secure your consultation, reach out at 01836545672 or 01822685066, or simply visit Room Number 3013. Dr. Mohammad Abdul Kader is a trusted specialist offering comprehensive solutions for those seeking expert kidney care.', 0, 'approved', 'unlocked');
