INSERT INTO `doctors` (`category_id`,`sub_category_id`,`name`,`designation`,`image_path`,`degree`,`higher_degree`,`phone`,`bmdc_number`,`email`,`work_place`,`specialist_in`,`experience_years`,`fee`,`about`,`priority`,`status`,`editing_status`) VALUES (7, 23, 'Prof.Dr.AMM Ehteshamul Haque', 'Professor & Head of Dept.(NEPHROLOGY DEPARTMENT), DEAN FACULTY OF MEDICINE,USTC. PRINCIPLE,INSTITUTE OF APPLIED HEALTH SCIENCE', 'assets/images/doctors/doc12.png', 'MBBS', 'MD(Nephrology) For Appointment Please Call : 01881928182 & 01834902335 (8am-2pm)', '01812345678', '12345', 'admin@gmail.com', 'National Hospital Chattogram & Sigma Lab Ltd.', 'Kidney Specialist', 10, 1000, 'Dr. AMM Ehteshamul Haque is a highly skilled nephrologist with expertise in various nephrological conditions. He offers comprehensive patient care, specializing in amyloidosis, acute kidney failure, diabetic kidney disorder, electrolyte disorders, glomerulonephritis, hypertension, kidney disease and failure, lupus nephritis, nephrotic syndrome, pyelonephritis, polycystic kidney disorder, renal insufficiency, and kidney transplant and dialysis. With his profound knowledge and experience, Dr. Haque provides effective management and treatment options for patients, ensuring the best possible outcomes in cases ranging from complex kidney disorders to end-stage renal disease. Dr AMM Ehteshamul Haque chamber at the National Hospital & Sigma Lab Ltd, located at 14/15 Mehedibagh, Chittagong. He is available for consultations from Everyday 6 pm to 9 pm (Friday off) Patients can contact him at 01881-928182 to schedule appointment.', 0, 'approved', 'unlocked');
